// The properties the public website shows.
//
// The bundled samples, with whatever the CMS has saved applied over them. This
// is what every public surface reads — the listing and its search, Featured
// Properties, Similar Properties and the detail pages.
//
// ── why it is generated rather than fetched ──────────────────────────────
// Gatsby renders these pages to static HTML at build time. Fetching the
// catalogue in the browser would mean the first paint showed twelve sample
// properties and then swapped them, and a search engine would only ever see
// the samples. So gatsby-node fetches once, writes cms-properties.json, and
// the whole site compiles against the result.
//
// The consequence is worth being explicit about: the public site changes when
// it is REBUILT, not when somebody presses Save. The CMS is immediately
// correct; the website is correct as of the last build.

import { builtAt, cmsProperties } from "../../generated/cms-properties.ts";
import { properties as samples } from "./property-data.ts";
import type { PropertyRecord } from "../../modules/property/types";

/** When the catalogue below was last read from the CMS. Null before any build. */
export const catalogueBuiltAt: string | null = builtAt;

/**
 * Samples, overridden by slug, with anything new appended.
 *
 * The same rule as the CMS's own `mergeProperties`, deliberately: a manager
 * must not see one list in the CMS and a different one on the website. A saved
 * record REPLACES the sample sharing its slug rather than appearing beside it,
 * and replacing keeps the original position so the list does not reorder
 * itself between builds.
 */
function merge(): PropertyRecord[] {
  if (!cmsProperties.length) return samples;

  const bySlug = new Map(samples.map((record) => [record.slug, record]));
  for (const record of cmsProperties) {
    if (record?.slug) bySlug.set(record.slug, record);
  }

  return [...bySlug.values()];
}

export const catalogue: PropertyRecord[] = merge();
