import React from "react";
import { Link } from "gatsby";
import { LuArrowRight, LuBath, LuBedDouble, LuMapPin, LuMaximize } from "react-icons/lu";

import type {
  PropertyCardLabels,
  PropertyCardTemplate,
} from "../../templates/property-card/default-template";
import type { Property } from "./types";

export type PropertyCardProps = {
  /** Structure, style and colour. Supplied by the primitive. */
  template: PropertyCardTemplate;
  property: Property;
  /** Builds the property page route from a slug. */
  hrefFor?: (slug: string) => string;
  /** Eager-load the first card or two; lazy-load the rest. */
  eager?: boolean;
  /**
   * "grid" stacks media over body; "list" puts them side by side and reveals
   * the summary. Same component, same markup — only a modifier class and one
   * extra paragraph, so there is no second card to keep in sync.
   */
  layout?: "grid" | "list";
  labels?: Partial<PropertyCardLabels>;
};

const number = new Intl.NumberFormat("en-US");

/**
 * A single property.
 *
 * Deliberately carousel-agnostic: it fills whatever box it is given at full
 * height, so the same component works inside a Swiper slide or a CSS grid
 * cell on Search Results.
 */
export default function PropertyCard({
  template,
  property,
  hrefFor = (slug) => `/properties/${slug}/`,
  eager = false,
  layout = "grid",
  labels: labelOverrides,
}: PropertyCardProps) {
  const labels = { ...template.labels, ...labelOverrides };
  const root = template.rootClass;
  const icon = template.layout.iconSize;

  const beds =
    property.bedrooms === 0
      ? labels.studio
      : `${property.bedrooms} ${
          property.bedrooms === 1 ? labels.bedsOne : labels.bedsMany
        }`;
  const baths = `${property.bathrooms} ${
    property.bathrooms === 1 ? labels.bathsOne : labels.bathsMany
  }`;
  const area = labels.area.replace("{n}", number.format(property.area));

  const isList = layout === "list";

  return (
    <article className={isList ? `${root} ${root}--list` : root}>
      <div className={`${root}__media`}>
        <img
          className={`${root}__image`}
          src={property.image}
          srcSet={property.imageSrcSet}
          sizes={
            property.imageSrcSet
              ? isList
                ? "(max-width: 760px) 90vw, 40vw"
                : "(max-width: 760px) 90vw, 33vw"
              : undefined
          }
          alt={property.imageAlt}
          loading={eager ? "eager" : "lazy"}
          decoding="async"
        />
        <div className={`${root}__tint`} aria-hidden="true" />

        {property.featured || property.availability ? (
          <div className={`${root}__badges`}>
            {property.featured ? (
              <span className={`${root}__badge ${root}__badge--featured`}>
                {labels.featured}
              </span>
            ) : null}
            {property.availability ? (
              <span className={`${root}__badge ${root}__badge--status`}>
                {property.availability}
              </span>
            ) : null}
          </div>
        ) : null}
      </div>

      <div className={`${root}__body`}>
        <p className={`${root}__type`}>{property.type}</p>

        <h3 className={`${root}__title`}>
          {/* Stretched link: the accessible name is the property title, while
              the ::after in CSS makes the whole card clickable. */}
          <Link className={`${root}__link`} to={hrefFor(property.slug)}>
            {property.title}
          </Link>
        </h3>

        <p className={`${root}__location`}>
          <span className={`${root}__location-icon`} aria-hidden="true">
            <LuMapPin size={template.layout.locationIconSize} strokeWidth={1.5} />
          </span>
          <span className={`${root}__location-text`}>{property.location}</span>
        </p>

        {isList && property.summary ? (
          <p className={`${root}__summary`}>{property.summary}</p>
        ) : null}

        <ul className={`${root}__stats`}>
          <li className={`${root}__stat`}>
            <span className={`${root}__stat-icon`} aria-hidden="true">
              <LuBedDouble size={icon} strokeWidth={1.5} />
            </span>
            {beds}
          </li>
          <li className={`${root}__stat`}>
            <span className={`${root}__stat-icon`} aria-hidden="true">
              <LuBath size={icon} strokeWidth={1.5} />
            </span>
            {baths}
          </li>
          <li className={`${root}__stat`}>
            <span className={`${root}__stat-icon`} aria-hidden="true">
              <LuMaximize size={icon} strokeWidth={1.5} />
            </span>
            {area}
          </li>
        </ul>

        <div className={`${root}__footer`}>
          <p className={`${root}__rent`}>
            ${number.format(property.rent)}
            <span className={`${root}__rent-period`}>{labels.rentPeriod}</span>
          </p>

          {/* Visual only — the card already has exactly one link. */}
          <span className={`${root}__cta`} aria-hidden="true">
            {labels.cta}
            <span className={`${root}__cta-arrow`}>
              <LuArrowRight size={14} strokeWidth={1.75} />
            </span>
          </span>
        </div>
      </div>
    </article>
  );
}
